[Fact]
public void AC3_GeneratedResolverIsEmittedIntoReferencingAssembly()
{
    Compilation app = CreateApp(RecordStructLib, AppSource);
    var (_, output, _) = RunGenerator(app);

    foreach (var tree in output.SyntaxTrees)
    {
        this.logger.WriteLine(tree.FilePath);
    }

    Assert.NotEmpty(output.GetSymbolsWithName("GeneratedMessagePackResolver", SymbolFilter.Type));

    var errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
    Assert.True(errors.Count == 0, "Compilation errors: " + string.Join(Environment.NewLine, errors));

    using var ms = new MemoryStream();
    var emit = output.Emit(ms);
    Assert.True(emit.Success, string.Join(Environment.NewLine, emit.Diagnostics));
}

[Fact]
public async Task AC5_AnalyzerDiagnosticsAgainstMetadataGenericStructDoNotCrash()
{
    // The referenced generic struct deliberately contains members that would trigger analyzer diagnostics
    // (members without a key attribute) so diagnostic-reporting paths run against a symbol without syntax.
    const string lib = """
        using MessagePack;
        namespace Lib;

        [MessagePackObject]
        public partial struct Item<T>
        {
            [Key(0)]
            public string Key { get; set; }

            public string NoKey { get; set; }

            public T Value;
        }
        """;

    Compilation app = CreateApp(lib, AppSource);
    var (driver, output, genDiagnostics) = RunGenerator(app);
    foreach (var r in driver.GetRunResult().Results)
    {
        Assert.True(r.Exception is null, $"Generator threw: {r.Exception}");
    }

    Assert.DoesNotContain(genDiagnostics, d => d.Id == "CS8785");

    var (exceptions, diagnostics) = await RunAnalyzerAsync(output);
    foreach (var d in diagnostics)
    {
        this.logger.WriteLine(d.ToString());
    }

    Assert.True(exceptions.Count == 0, "Analyzer threw: " + string.Join(Environment.NewLine, exceptions));
    Assert.DoesNotContain(diagnostics, d => d.Id == "AD0001");
}

[Fact]
public async Task AC6_SourceDeclaredGenericStructDiagnosticsStillAtSourceLocation()
{
    string input = """
        using MessagePack;

        [MessagePackObject]
        public struct Item<T>
        {
            [Key(0)]
            public string Key { get; set; }

            public string Extra { get; set; }
        }

        [MessagePackObject]
        public class Cmd
        {
            [Key(0)]
            public Item<int> Member { get; set; }
        }
        """;

    // Location of the source-declared member must be reported (once for the open declaration, and
    // via the closed Item<int> use), at the identifier of the property in source.
    var test = new VerifyCS.Test { TestCode = input };
    test.ExpectedDiagnostics.Add(new Microsoft.CodeAnalysis.Testing.DiagnosticResult("MsgPack004", DiagnosticSeverity.Error).WithSpan(9, 19, 9, 24).WithArguments("global::Item<T>", "Extra"));
    test.ExpectedDiagnostics.Add(new Microsoft.CodeAnalysis.Testing.DiagnosticResult("MsgPack004", DiagnosticSeverity.Error).WithSpan(9, 19, 9, 24).WithArguments("global::Item<T>", "Extra"));
    test.ExpectedDiagnostics.Add(new Microsoft.CodeAnalysis.Testing.DiagnosticResult("MsgPack004", DiagnosticSeverity.Error).WithSpan(9, 19, 9, 24).WithArguments("global::Item<int>", "Extra"));
    await test.RunAsync();
}

