using MessagePack.SourceGenerator.Analyzers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;

public class CountersignFinding1
{
    private readonly ITestOutputHelper output;

    public CountersignFinding1(ITestOutputHelper output) => this.output = output;

    [Theory]
    [InlineData("class")]
    [InlineData("struct")]
    public async Task UnattributedLocalTypeThroughReferencedGeneric_ReportsMsgPack003(string kind)
    {
        string defineSource = $$"""
using MessagePack;
namespace Lib
{
    [MessagePackObject]
    public {{kind}} Wrapper<T>
    {
        [Key(0)]
        public T Content { get; set; }
    }
}
""";

        string usageSource = """
using MessagePack;
using Lib;
namespace App
{
    public class Foo { }

    [MessagePackObject]
    public class Cmd
    {
        [Key(0)]
        public Wrapper<Foo> Value { get; set; }
    }

    [GeneratedMessagePackResolver]
    partial class AppResolver { }
}
""";

        ImmutableArray<MetadataReference> fx = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var refs = fx.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();
        var parse = CSharpParseOptions.Default.WithLanguageVersion(LanguageVersion.Latest);

        var lib = CSharpCompilation.Create("Lib", new[] { CSharpSyntaxTree.ParseText(defineSource, parse) }, refs, new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using var ms = new MemoryStream();
        var emit = lib.Emit(ms);
        Assert.True(emit.Success, string.Join("\n", emit.Diagnostics));
        refs.Add(MetadataReference.CreateFromImage(ms.ToArray()));

        var app = CSharpCompilation.Create("App", new[] { CSharpSyntaxTree.ParseText(usageSource, parse) }, refs, new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        var cwa = app.WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()));
        ImmutableArray<Diagnostic> diags = await cwa.GetAnalyzerDiagnosticsAsync();
        foreach (var d in diags)
        {
            this.output.WriteLine(d.ToString());
        }

        // Analyzer exceptions would surface as AD0001; ensure none.
        Assert.DoesNotContain(diags, d => d.Id == "AD0001");

        // Foo lacks [MessagePackObject] and has no formatter; MsgPack003 must be reported somewhere.
        Assert.Contains(diags, d => d.Id == "MsgPack003");
    }
}

